<?php require __DIR__.'/../config/functions.php'; require_admin(); $db=get_db(); header('Content-Type: application/json'); header('Content-Disposition: attachment; filename=backup.json'); $tables=array('admins','members','api_configs','model_logs','conversations','generations','site_settings'); $out=array(); foreach($tables as $t){$out[$t]=$db->query('SELECT * FROM '.$t)->fetchAll();} echo json_encode($out,JSON_UNESCAPED_UNICODE); 
